gadn(){return"\u0628\u0644\u062f \u0635\u063a\u064a\u0631\u0629 \u0628\u062a\u0646\u0627\u0645 \u0643\u0644 \u0644\u064a\u0644\u0629\u060c \u0648\u062a\u0635\u062d\u0649 \u0627\u0644\u0635\u0628\u062d \u0646\u0627\u0642\u0635\u0629 \u0648\u0627\u062d\u062f.\n\u0641\u064a\u0647 \u0646\u0627\u0633 \u0628\u064a\u0646\u0647\u0645 \u0645\u0634 \u0632\u064a \u0645\u0627 \u0628\u064a\u0642\u0648\u0644\u0648\u0627 \u2014 \u0648\u0627\u0644\u0628\u0627\u0642\u064a \u0644\u0627\u0632\u0645 \u064a\u0643\u0634\u0641\u0648\u0647\u0645 \u0642\u0628\u0644 \u0645\u0627 \u0627\u0644\u0628\u0644\u062f \u062a\u062e\u0644\u0635."},
gadj(){return"\u0627\u0644\u0623\u062f\u0648\u0627\u0631"},
