gadc(){return"\u0627\u0644\u0644\u064a\u0644"},
gadb(){return"\u0627\u0644\u0645\u0648\u0628\u0627\u064a\u0644 \u0628\u064a\u0644\u0641 \u0639\u0644\u0649 \u0627\u0644\u0643\u0644 \u0648\u0627\u062d\u062f \u0648\u0627\u062d\u062f. \u0643\u0644 \u0648\u0627\u062d\u062f \u0628\u064a\u0641\u062a\u062d\u0647 \u0644\u0648\u062d\u062f\u0647\u060c \u064a\u0639\u0645\u0644 \u062f\u0648\u0631\u0647\u060c \u0648\u064a\u0642\u0641\u0644\u0647 \u0648\u064a\u0645\u0631\u0651\u0631\u0647.\n\u0627\u0644\u0645\u0627\u0641\u064a\u0627 \u0628\u062a\u062e\u062a\u0627\u0631 \u062d\u062f\u060c \u0627\u0644\u062f\u0643\u062a\u0648\u0631 \u0628\u064a\u062d\u0645\u064a \u062d\u062f\u060c \u0648\u0627\u0644\u0645\u062d\u0642\u0642 \u0628\u064a\u0643\u0634\u0641 \u062d\u062f."},
