gUK(){return"\u0627\u0628\u0639\u062a \u0647\u0645\u0633\u0629"},
gahi(){return"\u0644\u0645\u064a\u0646\u061f"},
gahd(){return"\u0644\u063a\u0627\u064a\u0629 \u0661\u0662\u0660 \u062d\u0631\u0641"},
gahj(){return"\u0627\u0628\u0639\u062a"},
gahc(){return"\u0628\u0639\u062a\u0651 \u0647\u0645\u0633\u062a\u0643 \u0627\u0644\u0646\u0647\u0627\u0631\u062f\u0647"},
